import { useState } from 'react';
import { JxBadge, JxButton } from '@jinx-ui/react';

export interface UserRow {
  id: string;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: UserRow[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageUsers = users.slice(start, start + PAGE_SIZE);

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      <table className="jx-table">
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {pageUsers.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge variant={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
          {pageUsers.length === 0 && (
            <tr>
              <td colSpan={3} style={{ textAlign: 'center', color: 'var(--jx-fg-muted)' }}>
                Нет пользователей
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <div
        className="jx-cluster"
        style={{
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 'var(--jx-space-3)',
        }}
      >
        <JxButton
          variant="secondary"
          size="sm"
          disabled={currentPage <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          Назад
        </JxButton>

        <span style={{ color: 'var(--jx-fg-muted)', fontSize: 'var(--jx-font-size-sm)' }}>
          Страница {currentPage} из {totalPages}
        </span>

        <JxButton
          variant="secondary"
          size="sm"
          disabled={currentPage >= totalPages}
          onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
        >
          Вперёд
        </JxButton>
      </div>
    </div>
  );
}

